#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int h;
    int idx;
} Item;

int cmp(const void *a, const void *b) {
    Item *ia = (Item*)a;
    Item *ib = (Item*)b;
    if (ia->h != ib->h) return ib->h - ia->h;
    return ia->idx - ib->idx;
}

int main() {
    int N;
    scanf("%d", &N);
    Item *items = malloc(N * sizeof(Item));
    for (int i = 0; i < N; i++) {
        scanf("%d", &items[i].h);
        items[i].idx = i;
    }
    qsort(items, N, sizeof(Item), cmp);
    bool *active = calloc(N + 2, sizeof(bool));
    int segments = 0;
    int max_segments = 0;
    int i = 0;
    while (i < N) {
        int j = i;
        int h = items[i].h;
        while (j < N && items[j].h == h) {
            j++;
        }
        for (int k = i; k < j; k++) {
            int idx = items[k].idx;
            active[idx] = true;
            bool left = (idx > 0 && active[idx - 1]);
            bool right = (idx < N - 1 && active[idx + 1]);
            if (!left && !right) {
                segments++;
            } else if (left && right) {
                segments--;
            }
        }
        if (segments > max_segments) {
            max_segments = segments;
        }
        i = j;
    }
    printf("%d\n", max_segments + 1);
    free(items);
    free(active);
    return 0;
}
